import json
from pathlib import Path


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text, parse_constant=lambda c: (_raise(c)))
    except ValueError:
        raise
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    return data


def _raise(c):
    raise ValueError("non-standard JSON number: %s" % c)

def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    data = payloads[0]
    if isinstance(data, dict) and set(data) == {"name", "result"}:
        data = data["result"]

    departments = data["departments"]
    professors = data["professors"]

    dept_country = {}
    for d in departments:
        dept_country[d["id"]] = d["country"]

    countries = {}
    for p in professors:
        cs = set()
        for dep in p["departments"]:
            cs.add(dept_country[dep])
        countries[p["id"]] = sorted(cs)

    return {"name": contract["name"], "result": {"countries": countries}}

import json
from pathlib import Path


def _reject_nonfinite(obj):
    if isinstance(obj, float):
        if obj != obj or obj in (float("inf"), float("-inf")):
            raise ValueError("non-finite number")
    elif isinstance(obj, dict):
        for v in obj.values():
            _reject_nonfinite(v)
    elif isinstance(obj, list):
        for v in obj:
            _reject_nonfinite(v)


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text)
    except json.JSONDecodeError as e:
        raise ValueError("invalid JSON") from e
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _reject_nonfinite(data)
    return data

from datetime import date


def _parse_date(s):
    if not isinstance(s, str):
        raise ValueError("date must be string")
    try:
        return date.fromisoformat(s)
    except ValueError as e:
        raise ValueError("invalid date") from e


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    data = payloads[0]
    if isinstance(data, dict) and set(data) == {"name", "result"}:
        data = data["result"]

    departments = data["departments"]
    students = data["students"]
    as_of = _parse_date(data["as_of"])

    dept_ids = [d["id"] for d in departments]
    counts = {did: 0 for did in dept_ids}

    for student in students:
        sid = student["id"]
        seen = set()
        for enr in student["enrolments"]:
            dept = enr["department"]
            start = _parse_date(enr["start"])
            end = enr["end"]
            if end is not None:
                end = _parse_date(end)
                if end <= start:
                    raise ValueError("end must be after start")
            if start <= as_of and (end is None or as_of < end):
                key = (dept, sid)
                if key not in seen:
                    seen.add(key)
                    counts[dept] = counts.get(dept, 0) + 1

    return {"name": contract["name"], "result": {"counts": counts}}

