import json
from pathlib import Path


def _reject_nonfinite(obj):
    if isinstance(obj, float):
        if obj != obj or obj in (float("inf"), float("-inf")):
            raise ValueError("non-finite number")
    elif isinstance(obj, dict):
        for v in obj.values():
            _reject_nonfinite(v)
    elif isinstance(obj, list):
        for v in obj:
            _reject_nonfinite(v)


def load_payload(path):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    try:
        data = json.loads(text, parse_constant=lambda c: (_ for _ in ()).throw(ValueError("non-finite number")))
    except ValueError:
        raise
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _reject_nonfinite(data)
    return data

def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    raw = payloads[0]
    if isinstance(raw, dict) and set(raw) == {"name", "result"}:
        raw = raw["result"]

    eu = payloads[1]
    if isinstance(eu, dict) and set(eu) == {"name", "result"}:
        eu = eu["result"]
    students = payloads[2]
    if isinstance(students, dict) and set(students) == {"name", "result"}:
        students = students["result"]
    countries = payloads[3]
    if isinstance(countries, dict) and set(countries) == {"name", "result"}:
        countries = countries["result"]

    eligible_ids = set(eu["ids"])
    counts = students["counts"]
    country_map = countries["countries"]

    professors = []
    for pid in sorted(eligible_ids):
        eligible_departments = sorted(
            d for d in counts if counts[d] > 10 and d in _professor_departments(raw, pid)
        )
        if eligible_departments:
            professors.append({
                "id": pid,
                "countries": country_map.get(pid, []),
                "eligible_departments": eligible_departments,
            })

    return {"name": contract["name"], "result": {"professors": professors}}


def _professor_departments(raw, pid):
    for p in raw["professors"]:
        if p["id"] == pid:
            return set(p["departments"])
    return set()

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core = json.loads(core_path.read_text(encoding="utf-8"))
    components = core["components"]

    attention = []
    for name in sorted(components):
        result = components[name]
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            attention.append(name)
            continue
        for key in ("complete", "checkout", "committed", "ok"):
            if result.get(key) is False:
                attention.append(name)
                break
        else:
            for key in ("unavailable", "missing", "conflicts", "unreachable"):
                v = result.get(key)
                if isinstance(v, (list, dict, str)) and len(v) > 0:
                    attention.append(name)
                    break

    serialized = json.dumps(
        core, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    sha = hashlib.sha256(serialized).hexdigest()

    report = {
        "title": "大学任职、在读人数与国家集合查询",
        "component_count": len(components),
        "sha256": sha,
        "attention": sorted(set(attention)),
    }

    out = ROOT / "outputs" / "final_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()

