def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    payload = payloads[0]
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        payload = payload["result"]
    departments = payload["departments"]
    professors = payload["professors"]
    eu = payload["eu"]

    country_by_dept = {}
    for d in departments:
        country_by_dept[d["id"]] = d["country"]

    eu_set = set(eu)
    ids = []
    for p in professors:
        for dept in p["departments"]:
            if country_by_dept[dept] in eu_set:
                ids.append(p["id"])
                break
    ids.sort()
    return {"name": contract["name"], "result": {"ids": ids}}

from datetime import date


def _parse_date(s):
    if not isinstance(s, str):
        raise ValueError("date must be string")
    try:
        return date.fromisoformat(s)
    except ValueError as e:
        raise ValueError("invalid date") from e


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    data = payloads[0]
    if isinstance(data, dict) and set(data) == {"name", "result"}:
        data = data["result"]

    departments = data["departments"]
    students = data["students"]
    as_of = _parse_date(data["as_of"])

    dept_ids = [d["id"] for d in departments]
    counts = {did: 0 for did in dept_ids}

    for student in students:
        sid = student["id"]
        seen = set()
        for enr in student["enrolments"]:
            dept = enr["department"]
            start = _parse_date(enr["start"])
            end = enr["end"]
            if end is not None:
                end = _parse_date(end)
                if end <= start:
                    raise ValueError("end must be after start")
            if start <= as_of and (end is None or as_of < end):
                key = (dept, sid)
                if key not in seen:
                    seen.add(key)
                    counts[dept] = counts.get(dept, 0) + 1

    return {"name": contract["name"], "result": {"counts": counts}}

def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    data = payloads[0]
    if isinstance(data, dict) and set(data) == {"name", "result"}:
        data = data["result"]

    departments = data["departments"]
    professors = data["professors"]

    dept_country = {}
    for d in departments:
        dept_country[d["id"]] = d["country"]

    countries = {}
    for p in professors:
        cs = set()
        for dep in p["departments"]:
            cs.add(dept_country[dep])
        countries[p["id"]] = sorted(cs)

    return {"name": contract["name"], "result": {"countries": countries}}

def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    raw = payloads[0]
    if isinstance(raw, dict) and set(raw) == {"name", "result"}:
        raw = raw["result"]

    eu = payloads[1]
    if isinstance(eu, dict) and set(eu) == {"name", "result"}:
        eu = eu["result"]
    students = payloads[2]
    if isinstance(students, dict) and set(students) == {"name", "result"}:
        students = students["result"]
    countries = payloads[3]
    if isinstance(countries, dict) and set(countries) == {"name", "result"}:
        countries = countries["result"]

    eligible_ids = set(eu["ids"])
    counts = students["counts"]
    country_map = countries["countries"]

    professors = []
    for pid in sorted(eligible_ids):
        eligible_departments = sorted(
            d for d in counts if counts[d] > 10 and d in _professor_departments(raw, pid)
        )
        if eligible_departments:
            professors.append({
                "id": pid,
                "countries": country_map.get(pid, []),
                "eligible_departments": eligible_departments,
            })

    return {"name": contract["name"], "result": {"professors": professors}}


def _professor_departments(raw, pid):
    for p in raw["professors"]:
        if p["id"] == pid:
            return set(p["departments"])
    return set()

